class Countdown:
    """An iterator class: remembers where it is."""
    def __init__(self, start):
        self.current = start

    def __iter__(self):
        return self

    def __next__(self):
        if self.current <= 0:
            raise StopIteration
        self.current -= 1
        return self.current + 1

print(list(Countdown(3)), sum(Countdown(4)))
c = Countdown(2)
print(list(c), list(c))              # iterators are ONE-SHOT: the second pass is empty

lines = iter(["a", "b", "", "c"])
